(() => {
 const svg=path=>`<svg viewBox="0 0 24 24" aria-hidden="true">${path}</svg>`;
 const icons={arrow:svg('<path d="M5 12h14m-6-6 6 6-6 6"/>'),back:svg('<path d="M19 12H5m6-6-6 6 6 6"/>'),leaf:svg('<path d="M20 3C10 3 4 7 4 13a6 6 0 0 0 6 6c6 0 10-6 10-16ZM4 21 15 10"/>'),search:svg('<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>'),chevron:svg('<path d="m7 10 5 5 5-5"/>'),close:svg('<path d="m6 6 12 12M6 18 18 6"/>'),check:svg('<path d="m5 12 4 4L19 6"/>'),compare:svg('<rect x="3" y="5" width="7" height="15" rx="1"/><rect x="14" y="5" width="7" height="15" rx="1"/><path d="M6 9h1m10 0h1M6 13h1m10 0h1"/>'),filter:svg('<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>'),phone:svg('<path d="M5 4h4l2 5-3 2a16 16 0 0 0 5 5l2-3 5 2v4c-8 2-18-8-15-15Z"/>'),external:svg('<path d="M14 3h7v7m0-7L10 14M10 4H4v16h16v-6"/>'),car:svg('<path d="m4 10 2-6h12l2 6M3 10h18v8H3Zm2 8v3m14-3v3M6 14h2m8 0h2"/>'),pause:svg('<path d="M9 6v12M15 6v12"/>'),play:svg('<path d="M8 5.5v13l10.5-6.5Z"/>')};
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
 const button=(label,href,kind='primary',icon='arrow',attr='')=>`<a class="button ${kind} eh-button" href="${esc(href)}" ${attr}><span>${label}</span><span class="action-icon">${icons[icon]}</span></a>`;
 let promise,core,data,state={query:'',brand:'all',condition:'all',fuel:'all',budget:0,sort:'featured'},selected=[],shown=16;
 const brands=['Volkswagen','Audi','Škoda','CUPRA','SEAT'],brandAsset={Volkswagen:'volkswagen',Audi:'audi','Škoda':'skoda',CUPRA:'cupra',SEAT:'seat'};
 const heroIds=['vw-id-3-pa-pro-3','skoda-elroq-61','audi-a3-sportback-sline-45-tfsi-e-stronic'];
 const loading='<div class="eh-loading" role="status">Loading the eHub collection…</div>';
 function load(){return promise||(promise=Promise.all([fetch('data/ehub.json').then(r=>{if(!r.ok)throw Error();return r.json()}),import('./ehub-core.mjs')]).then(([d,c])=>{data=d;core=c;return d}).catch(e=>{promise=null;throw e}));}
 window.renderUniEhub=()=>{queueMicrotask(mount);return `<div class="ehub-page" id="ehubPage"><div class="eh-wrap">${loading}</div></div>`};
 window.renderUniEhubCar=id=>{queueMicrotask(()=>mountCar(id));return `<div class="ehub-page eh-detail-page" id="ehubCar"><div class="eh-wrap">${loading}</div></div>`};
 function error(root){root.innerHTML=`<div class="eh-empty"><h1>Explore the eHub collection.</h1><p>The preview could not load. You can still browse the original listings.</p>${button('Open Unicars eHub','https://www.ehub.unicars.com.cy/','primary','external')}</div>`;}
 async function mount(){const root=document.getElementById('ehubPage');if(!root)return;try{await load();if(!root.isConnected)return;root.innerHTML=page();bind(root);update(root);renderHero(root);setupHeroFilm(root);bindImages(root);reveal(root);}catch(e){if(root.isConnected)error(root)}}
 function heroStats(){const ms=data.models||[];return {count:ms.length,save:Math.max(0,...ms.map(m=>m.saving||0))}}
 function page(){const st=heroStats();return `<section class="eh-hero" aria-labelledby="ehHeroTitle"><div class="eh-wrap"><div class="eh-hero-frame"><video class="eh-hero-film" muted playsinline loop preload="none" poster="assets/ehub-hero-poster.jpg" tabindex="-1" aria-hidden="true" data-src="assets/ehub-hero-film.mp4" data-mobile-src="assets/ehub-hero-film-mobile.mp4"></video><div class="eh-hero-shade" aria-hidden="true"></div><button type="button" class="eh-film-toggle" data-eh-film aria-label="Pause background video" hidden>${icons.pause}</button><div class="eh-hero-content"><p class="eh-hero-proof"><span class="eh-hero-brands" aria-hidden="true">${brands.map(b=>`<span><img src="assets/brands/${brandAsset[b]}.svg" alt="" width="20" height="16"></span>`).join('')}</span><span>${st.count} cars${st.save?` · Save up to ${money(st.save)}`:''}</span></p><h1 id="ehHeroTitle">Your next car.<br>A better deal.</h1><p class="eh-hero-sub">Specific cars with published offer prices and the equipment included.</p><div class="eh-hero-actions"><button type="button" class="button white eh-button" data-eh-browse>Explore the cars <span class="action-icon">${icons.car}</span></button>${button('How eHub works','#ehow','ghost','check','data-eh-how')}</div></div><div class="eh-hero-offers" id="ehFeatured" aria-label="Featured offers"></div></div></div></section>
 <section class="eh-collection eh-wrap" id="ehCollection" aria-labelledby="ehCollectionTitle" data-ui><header class="eh-collection-title"><div><h2 id="ehCollectionTitle">Find the one for you.</h2><p>Specific cars. Clear prices. Your choice.</p></div></header><div class="eh-brands" role="group" aria-label="Filter eHub listings by brand"><button type="button" data-eh-brand="all" aria-pressed="${state.brand==='all'}"><span>All brands</span><small>${data.models.length}</small></button>${brands.map(b=>`<button type="button" data-eh-brand="${b}" aria-pressed="${state.brand===b}"><img src="assets/brands/${brandAsset[b]}.svg" alt="" width="34" height="25"><span>${b}</span><small>${data.models.filter(m=>m.brand===b).length}</small></button>`).join('')}</div>
 <div class="eh-tools"><label class="eh-search">${icons.search}<span class="eh-sr">Search model, colour or vehicle reference</span><input type="search" id="ehSearch" placeholder="Model, colour or vehicle reference" value="${esc(state.query)}" autocomplete="off"></label><button type="button" class="eh-filter-toggle" aria-expanded="false" aria-controls="ehExtraFilters">${icons.filter}Filters <span id="ehFilterCount"></span>${icons.chevron}</button>${select('sort','Sort by',[['featured','Featured'],['price-low','Price: low to high'],['price-high','Price: high to low'],['saving','Largest saving'],['name','Brand & model: A–Z']])}</div>
 <div class="eh-extra-filters" id="ehExtraFilters">${select('condition','Vehicle type',[['all','All vehicle types'],['New car','New cars'],['Test-drive car','Test-drive cars'],['Audi Approved','Audi Approved']])}${select('fuel','Engine',[['all','All engines'],...Object.entries(core.fuelNames).filter(([k])=>k!=='unknown')])}${select('budget','Offer price',[[0,'Any budget'],[20000,'Up to €20,000'],[30000,'Up to €30,000'],[40000,'Up to €40,000'],[50000,'Up to €50,000'],[70000,'Up to €70,000']])}</div>
 <div class="eh-result-row"><p id="ehResultCount" role="status" aria-live="polite"></p></div><div class="eh-active-filters" id="ehActiveFilters"></div><div class="eh-card-grid" id="ehCars"></div><div class="eh-more" id="ehMore"></div><p class="eh-collection-note">Savings compare the offer and reference prices published on eHub. Images are indicative. Confirm price, equipment and availability with Unicars.</p></section>
 <section class="eh-how eh-wrap" id="ehow" aria-labelledby="ehHowTitle"><div class="eh-how-intro"><h2 id="ehHowTitle">A simpler way<br>to find your next car.</h2><p>Browse at your pace. Enquire when you’re ready.</p>${button('Speak to our team','#contact','secondary','phone')}</div><div class="eh-how-list"><article>${icons.search}<div><h3>Find your shortlist.</h3><p>Filter the published cars by brand, engine, price and vehicle type. Compare up to three side by side.</p></div></article><article>${icons.compare}<div><h3>See the full picture.</h3><p>Check the exact version, colour, equipment, offer price and reference before choosing.</p></div></article><article>${icons.phone}<div><h3>Start a conversation.</h3><p>Continue to the original eHub listing to express your interest. The team confirms availability and next steps. An enquiry does not reserve a car.</p></div></article></div></section>
 <section class="eh-faq eh-wrap" aria-labelledby="ehFaqTitle"><div class="eh-faq-intro"><h2 id="ehFaqTitle">Before you<br>make your move.</h2><p>A few things to know about eHub.</p></div><div class="eh-questions">${[
 ['Is an enquiry a purchase or reservation?','No. An enquiry is a nonbinding expression of interest. A reservation requires arranging an order and deposit with the sales team.'],
 ['Are all eHub cars electric?','No. The collection includes petrol, diesel, hybrid and electric cars. Use the engine filter to explore your preferred type.'],
 ['Can I change a listed car’s equipment?','Each listing represents a specific car with its stated equipment. If you want a different configuration, speak to Unicars about the wider model range.'],
 ['What happens after I enquire?','A sales consultant contacts you to discuss the car, confirm availability and explain the next steps. Sending an enquiry does not require a payment.']].map(([q,a])=>`<details><summary>${q}<span>${icons.chevron}</span></summary><p>${a}</p></details>`).join('')}</div></section>
 <section class="eh-closing"><div class="eh-wrap eh-closing-grid"><div><img src="${esc(data.models.find(m=>m.id==='skoda-elroq-61').images[1]?.src||data.models[0].images[0].src)}" alt="Škoda Elroq listing model view" width="1100" height="1100" loading="lazy"></div><div><h2>Let’s find your<br>next chapter.</h2><p>Need a hand choosing? Speak to the team about a car you’ve seen or explore the full Unicars model range.</p><div>${button('Contact Unicars','#contact','primary','phone')}${button('Browse the model range','#prices','secondary','car')}</div></div></div></section>
 <div class="eh-wrap eh-source-footer"><p>Listings and prices checked against Unicars eHub on 20 November 2026. This preview is a published snapshot, not a live inventory connection.</p>${button('View original eHub','https://www.ehub.unicars.com.cy/','secondary','external','target="_blank" rel="noopener"')}</div><div id="ehCompareTray" class="eh-compare-tray" hidden></div><p class="eh-compare-feedback eh-sr" id="ehCompareMessage" role="status" aria-live="polite"></p><dialog id="ehCompareDialog" class="eh-compare-dialog" aria-labelledby="ehCompareTitle"></dialog>`;}
 function select(name,label,options){const value=String(state[name]),current=options.find(([v])=>String(v)===value)?.[1]||options[0][1];return `<details class="eh-select" data-eh-select="${name}"><summary><span><small>${label}</small><strong>${current}</strong></span>${icons.chevron}</summary><div class="eh-select-options" role="group" aria-label="${label}">${options.map(([v,text])=>`<label><input type="radio" name="eh-${name}" value="${esc(v)}" ${String(v)===value?'checked':''}><span>${text}</span>${icons.check}</label>`).join('')}</div></details>`;}
 function featureModels(){return heroIds.map(id=>data.models.find(m=>m.id===id)).filter(Boolean)}
 function renderHero(root){
  const items=featureModels(),host=root.querySelector('#ehFeatured');if(!host)return;if(!items.length){host.hidden=true;return}
  host.innerHTML=`<p class="eh-offers-label">Featured offers</p><ul class="eh-offers-list">${items.map(m=>{const name=m.displayModel||m.model;return `<li><a class="eh-offer-link" href="#ehub-car-${esc(m.id)}" aria-label="${esc(`${m.brand} ${name}, offer price ${money(m.price)}${m.saving?`, save ${money(m.saving)}`:''}. View car`)}"><span class="eh-offer-thumb"><img src="${esc(m.images[0].src)}" alt="" width="120" height="80" loading="lazy" draggable="false"></span><span class="eh-offer-copy"><small>${esc(m.brand)}</small><strong>${esc(name)}</strong></span><span class="eh-offer-figures"><strong>${money(m.price)}</strong>${m.saving?`<small>Save ${money(m.saving)}</small>`:''}</span><span class="eh-offer-arrow" aria-hidden="true">${icons.arrow}</span></a></li>`}).join('')}</ul>`;
 }
 function setupHeroFilm(root){const video=root.querySelector('.eh-hero-film'),toggle=root.querySelector('[data-eh-film]');if(!video||!toggle)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)');let userPaused=false;
  const label=()=>{const playing=!video.paused;toggle.innerHTML=playing?icons.pause:icons.play;toggle.setAttribute('aria-label',playing?'Pause background video':'Play background video')};
  const play=()=>{if(!video.src)video.src=matchMedia('(max-width: 800px)').matches?video.dataset.mobileSrc:video.dataset.src;video.muted=true;video.play().then(()=>{toggle.hidden=false;label()}).catch(()=>{})};
  video.addEventListener('play',label);video.addEventListener('pause',label);
  toggle.addEventListener('click',()=>{if(video.paused){userPaused=false;play()}else{userPaused=true;video.pause()}});
  reduced.addEventListener('change',()=>{if(reduced.matches)video.pause()});
  if(reduced.matches||navigator.connection?.saveData){toggle.hidden=false;label()}
  new IntersectionObserver(entries=>{if(!video.isConnected)return;if(entries[0].isIntersecting){if(!userPaused&&!reduced.matches&&!navigator.connection?.saveData)play()}else video.pause()},{threshold:.1}).observe(video);
 }

 function gallery(m,large=false){return `<div class="eh-gallery ${large?'eh-gallery-large':''} ${m.approved?'eh-gallery-approved':''}" data-eh-gallery="${m.id}" role="region" aria-roledescription="carousel" aria-label="${esc(m.brand+' '+(m.displayModel||m.model))} listing images" ${m.images.length>1?'tabindex="0"':''}><div class="eh-gallery-track">${m.images.map((im,i)=>`<img src="${esc(im.src)}" alt="${esc(im.alt)}" width="1100" height="1100" loading="${large&&i===0?'eager':'lazy'}" decoding="async">`).join('')}</div>${m.images.length>1?`<button type="button" class="eh-image-prev" data-eh-image-step="-1" aria-label="Previous listing image" disabled>${icons.back}</button><button type="button" class="eh-image-next" data-eh-image-step="1" aria-label="Next listing image">${icons.arrow}</button><div class="eh-image-dots">${m.images.map((_,i)=>`<button type="button" data-eh-image="${i}" aria-label="Listing image ${i+1}" aria-current="${i===0}"></button>`).join('')}</div>`:''}</div>`;}
 function card(m){return `<article class="eh-card"><div class="eh-card-image"><span class="eh-condition">${esc(m.condition)}</span>${m.saving?`<span class="eh-saving">Save ${money(m.saving)}</span>`:''}${gallery(m)}</div><div class="eh-card-body"><p class="eh-brand-label">${esc(m.brand)}</p><h3>${esc(m.displayModel||m.model)}</h3><p class="eh-trim" title="${esc(m.model)}">${esc(m.trim||m.model)}</p><div class="eh-tags"><span>${esc(core.fuelNames[m.powertrain])}</span>${m.transmission?`<span>${m.transmission}</span>`:''}</div><div class="eh-listing-color"><span>Colour</span><strong>${esc(m.color||'See listing details')}</strong></div><div class="eh-card-price"><div><span>Offer price</span><strong>${money(m.price)}</strong></div>${m.comparePrice?`<div class="eh-reference-price"><span>eHub reference</span><s>${money(m.comparePrice)}</s></div>`:''}</div>${button('View this car','#ehub-car-'+m.id)}<div class="eh-card-foot"><label><input type="checkbox" data-eh-compare="${m.id}" ${selected.includes(m.id)?'checked':''} aria-label="Compare ${esc(m.brand+' '+m.model+' '+m.reference)}">Compare</label><span>${esc(m.reference)}</span></div></div></article>`;}
 function filterChips(){const labels={brand:state.brand,condition:state.condition,fuel:core.fuelNames[state.fuel],budget:state.budget?`Up to ${money(state.budget)}`:'',query:state.query?`“${state.query}”`:''};return Object.entries(labels).filter(([k,v])=>v&&state[k]!==initial(k)).map(([k,v])=>`<button type="button" data-eh-remove="${k}" class="eh-chip">${esc(v)}${icons.close}<span class="eh-sr">Remove filter</span></button>`).join('')}
 function initial(k){return core.initialEhubFilters[k]}
 function update(root){const found=core.filterEhub(data.models,state);root.querySelector('#ehCars').innerHTML=found.length?found.slice(0,shown).map(card).join(''):`<div class="eh-empty">${icons.search}<h3>No cars match these filters.</h3><p>Try a different brand, a higher budget or fewer filters.</p><button type="button" class="button primary eh-button" data-eh-reset>Clear filters <span class="action-icon">${icons.close}</span></button></div>`;root.querySelector('#ehResultCount').innerHTML=`<strong>${found.length}</strong> ${found.length===1?'car':'cars'}${found.length!==data.models.length?' matching your search':''}`;root.querySelector('#ehActiveFilters').innerHTML=filterChips();root.querySelector('#ehMore').innerHTML=found.length>shown?`<p>Showing ${Math.min(shown,found.length)} of ${found.length} cars</p><button type="button" class="button secondary eh-button" data-eh-more>Show more cars <span class="action-icon">${icons.car}</span></button>`:'';root.querySelectorAll('[data-eh-brand]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ehBrand===state.brand)));root.querySelectorAll('[data-eh-select]').forEach(d=>{const input=d.querySelector(`input[value="${state[d.dataset.ehSelect]}"]`);if(input){input.checked=true;d.querySelector('summary strong').textContent=input.nextElementSibling.textContent}});const search=root.querySelector('#ehSearch');if(search.value!==state.query)search.value=state.query;root.querySelector('#ehFilterCount').textContent=['condition','fuel','budget'].filter(k=>state[k]!==initial(k)).length||'';bindImages(root);updateTray(root);}
 function updateTray(root){const tray=root.querySelector('#ehCompareTray');tray.hidden=!selected.length;root.classList.toggle('eh-has-comparison',!!selected.length);tray.innerHTML=selected.length?`<div class="eh-tray-cars">${selected.map(id=>{const m=data.models.find(m=>m.id===id);return `<div><img src="${esc(m.images[0].src)}" alt="" width="100" height="70"><span>${esc(m.displayModel||m.model)}<small>${money(m.price)}</small></span><button type="button" data-eh-uncompare="${id}" aria-label="Remove ${esc(m.reference)} from comparison">${icons.close}</button></div>`}).join('')}</div><div class="eh-tray-actions"><button type="button" class="button primary eh-button" data-eh-open-compare ${selected.length<2?'disabled':''}>Compare ${selected.length} ${selected.length===1?'car':'cars'}<span class="action-icon">${icons.compare}</span></button><button type="button" class="button secondary eh-button eh-clear-compare" data-eh-clear-compare><span>Clear</span><span class="action-icon">${icons.close}</span></button></div>`:'';root.querySelectorAll('[data-eh-compare]').forEach(input=>{input.checked=selected.includes(input.dataset.ehCompare);input.disabled=selected.length>=3&&!input.checked});}
 function setCompare(id,root){const next=core.nextComparison(selected,id);selected=next.ids;root.querySelector('#ehCompareMessage').textContent=next.error||(selected.length?`${selected.length} cars selected. ${selected.length<2?'Choose one more car to compare.':'Ready to compare.'}`:'Comparison cleared.');updateTray(root)}
 function openComparison(root){const dialog=root.querySelector('#ehCompareDialog'),items=selected.map(id=>data.models.find(m=>m.id===id));dialog.innerHTML=`<header><div><h2 id="ehCompareTitle">Your cars. Side by side.</h2><p>Compare the specific versions you’ve selected.</p></div><button type="button" data-eh-close-compare aria-label="Close comparison">${icons.close}</button></header><div class="eh-compare-scroll"><table><caption class="eh-sr">Selected eHub vehicle comparison</caption><thead><tr><th scope="col">Your shortlist</th>${items.map(m=>`<th scope="col"><img src="${esc(m.images[0].src)}" alt="${esc(m.images[0].alt)}" width="300" height="200"><span>${esc(m.brand)}</span><strong>${esc(m.displayModel||m.model)}</strong><small>${esc(m.trim||'')}</small></th>`).join('')}</tr></thead><tbody>${[
 ['Offer price',m=>money(m.price)],['Saving',m=>m.saving?money(m.saving)+' vs eHub reference':'No reference price supplied'],['Vehicle type',m=>m.condition],['Engine',m=>core.fuelNames[m.powertrain]],['Gearbox',m=>m.transmission||'See listing'],['Colour',m=>m.color||'See listing'],['Vehicle reference',m=>m.reference],['Power',m=>m.technical.find(x=>/^Output:/i.test(x))?.replace(/^Output:\s*/i,'')||'Not stated'],['Electric range',m=>m.technical.find(x=>/Electric Range/i.test(x))?.replace(/^.*?:\s*/,'')||'Not stated'],['Extra equipment',m=>m.equipment.slice(0,3).join(' · ')||'See full listing']].map(([label,value])=>`<tr><th scope="row">${label}</th>${items.map(m=>`<td>${esc(value(m))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Explore this car</th>${items.map(m=>`<td>${button('View car','#ehub-car-'+m.id,'primary','arrow','data-eh-leave-compare')}</td>`).join('')}</tr></tbody></table></div><p class="eh-compare-note">Published snapshot. Confirm price and availability. Images are indicative.</p>`;dialog.showModal();document.body.classList.add('ehub-dialog-open');dialog.addEventListener('close',()=>document.body.classList.remove('ehub-dialog-open'),{once:true});}
 function bind(root){let timer;const change=()=>{shown=16;update(root)};root.addEventListener('input',e=>{if(e.target.id==='ehSearch'){state.query=e.target.value;clearTimeout(timer);timer=setTimeout(change,140)}});root.addEventListener('change',e=>{const input=e.target;if(input.matches('[data-eh-compare]')){setCompare(input.dataset.ehCompare,root);return}if(input.name?.startsWith('eh-')){const key=input.name.slice(3);state[key]=key==='budget'?Number(input.value):input.value;const d=input.closest('details');d.open=false;d.querySelector('summary').focus();change()}});root.addEventListener('click',e=>{if(e.target.closest('[data-eh-browse]')){e.preventDefault();root.querySelector('#ehCollection').scrollIntoView({behavior:motion()});return}if(e.target.closest('[data-eh-how]')){e.preventDefault();e.stopPropagation();root.querySelector('#ehow').scrollIntoView({behavior:motion()});return}const b=e.target.closest('button');if(b?.hasAttribute('data-eh-brand')){state.brand=b.dataset.ehBrand;change()}if(b?.hasAttribute('data-eh-more')){const old=shown;shown+=16;update(root);const next=root.querySelectorAll('.eh-card h3')[old];next?.setAttribute('tabindex','-1');next?.focus({preventScroll:true})}if(b?.hasAttribute('data-eh-reset')){state={...core.initialEhubFilters};change()}if(b?.hasAttribute('data-eh-remove')){state[b.dataset.ehRemove]=initial(b.dataset.ehRemove);change();root.querySelector('#ehSearch').focus()}if(b?.matches('.eh-filter-toggle')){const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));root.querySelector('#ehExtraFilters').classList.toggle('is-open',open)}if(b?.hasAttribute('data-eh-uncompare'))setCompare(b.dataset.ehUncompare,root);if(b?.hasAttribute('data-eh-clear-compare')){selected=[];updateTray(root)}if(b?.hasAttribute('data-eh-open-compare'))openComparison(root);if(b?.hasAttribute('data-eh-close-compare')||e.target.closest('[data-eh-leave-compare]'))root.querySelector('#ehCompareDialog').close();if(e.target===root.querySelector('#ehCompareDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});}
 const motion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth';
 function bindImages(root){root.querySelectorAll('[data-eh-gallery]').forEach(g=>{if(g.dataset.bound||g.querySelectorAll('img').length<2)return;g.dataset.bound='true';const track=g.querySelector('.eh-gallery-track'),count=track.children.length;let current=0;const sync=()=>{current=Math.max(0,Math.min(count-1,Math.round(track.scrollLeft/track.clientWidth)));g.querySelector('.eh-image-prev').disabled=current===0;g.querySelector('.eh-image-next').disabled=current===count-1;g.querySelectorAll('[data-eh-image]').forEach((b,i)=>b.setAttribute('aria-current',String(i===current)))};const move=i=>track.scrollTo({left:Math.max(0,Math.min(count-1,i))*track.clientWidth,behavior:motion()});g.addEventListener('click',e=>{const step=e.target.closest('[data-eh-image-step]'),dot=e.target.closest('[data-eh-image]');if(step)move(current+Number(step.dataset.ehImageStep));if(dot)move(Number(dot.dataset.ehImage))});g.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();move(e.key==='Home'?0:e.key==='End'?count-1:current+(e.key==='ArrowRight'?1:-1))}});track.addEventListener('scroll',sync,{passive:true});});}
 function reveal(root){if(!('IntersectionObserver' in window))return;const observer=new IntersectionObserver(entries=>{entries.forEach(({target,isIntersecting})=>{if(isIntersecting){target.classList.add('eh-visible');observer.unobserve(target)}})},{threshold:.12});root.querySelectorAll('.eh-how-intro,.eh-how-list article,.eh-faq-intro,.eh-questions,.eh-closing-grid>div').forEach(el=>{el.classList.add('eh-reveal');observer.observe(el)})}
 document.addEventListener('click',e=>{document.querySelectorAll('.eh-select[open]').forEach(d=>{if(!d.contains(e.target))d.open=false})});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.eh-select[open]').forEach(d=>{d.open=false;d.querySelector('summary').focus()})});window.addEventListener('hashchange',()=>document.body.classList.remove('ehub-dialog-open'));
 async function mountCar(id){const root=document.getElementById('ehubCar');if(!root)return;try{await load();if(!root.isConnected)return;const m=data.models.find(m=>m.id===id);if(!m){root.querySelector('.eh-wrap').innerHTML=`<div class="eh-empty"><h1>This listing couldn’t be found.</h1>${button('Back to eHub','#available')}</div>`;return}root.innerHTML=`<div class="eh-wrap"><div class="eh-detail-back">${button('Back to eHub','#available','secondary','back')}</div><div class="eh-detail-grid"><div><div class="eh-detail-photo">${gallery(m,true)}<span class="eh-condition">${esc(m.condition)}</span></div><p class="eh-photo-caption">Indicative listing images · confirm the actual car’s appearance with Unicars.</p><div class="eh-equipment"><h2>Included extra equipment.</h2><p>These extras are included in the published offer price.</p>${m.equipment.length?`<ul>${m.equipment.map(item=>`<li>${icons.check}<span>${esc(item)}</span></li>`).join('')}</ul>`:'<p>See the original listing for the full equipment details.</p>'}${m.standardEquipmentSource?button('View standard equipment',m.standardEquipmentDocument||m.standardEquipmentSource,'secondary','external','target="_blank" rel="noopener"'):''}</div></div><div class="eh-detail-information"><p class="eh-detail-brand">${esc(m.brand)}</p><h1>${esc(m.displayModel||m.model)}</h1><p class="eh-detail-trim">${esc(m.trim||m.model)}</p><div class="eh-tags"><span>${esc(core.fuelNames[m.powertrain])}</span>${m.transmission?`<span>${m.transmission}</span>`:''}<span>${esc(m.condition)}</span></div><div class="eh-detail-price"><span>Published offer price</span><strong>${money(m.price)}</strong>${m.comparePrice?`<p><s>${money(m.comparePrice)}</s> eHub reference price</p><span class="eh-detail-saving">Save ${money(m.saving)}</span>`:''}<small>Taxes included · availability to confirm</small></div><dl class="eh-detail-summary"><div><dt>Colour</dt><dd>${esc(m.color||'See listing')}</dd></div><div><dt>Vehicle reference</dt><dd>${esc(m.reference)}</dd></div></dl><div class="eh-detail-cta">${button('Enquire on eHub',m.source,'primary','external','target="_blank" rel="noopener"')}${button('Request a test drive','#test-drive?model=ehub-car-'+m.id,'secondary','car')}${button('Call Unicars','tel:+35722204222','secondary','phone')}</div><p class="eh-enquiry-note">Continue to the original listing to express your interest. Your enquiry does not reserve the car or place an order.</p><section class="eh-source-info"><h2>Vehicle information.</h2><dl><div><dt>Source vehicle status</dt><dd>${esc(m.sourceCondition||m.condition)}</dd></div>${m.year?`<div><dt>Published year</dt><dd>${m.year}</dd></div>`:''}${m.warrantyStart?`<div><dt>Warranty start date</dt><dd>${esc(m.warrantyStart)}</dd></div>`:''}<div><dt>Mileage</dt><dd>${esc(m.mileageText||'Not stated in the published listing')}</dd></div><div><dt>Source availability</dt><dd>${m.sourceAvailable?'Listed at source · confirmation required':'Marked unavailable at source'}</dd></div></dl></section><details class="eh-technical" open><summary>Technical details ${icons.chevron}</summary><dl>${m.technical.map(t=>{const at=t.indexOf(':');return at>-1?`<div><dt>${esc(t.slice(0,at))}</dt><dd>${esc(t.slice(at+1).trim())}</dd></div>`:`<div><dt>${esc(t)}</dt><dd></dd></div>`}).join('')}</dl></details>${m.sourceSections?.length?`<details class="eh-source-extra"><summary>All published vehicle details <span aria-hidden="true">+</span></summary>${m.sourceSections.map(section=>`<section><h3>${esc(section.title)}</h3><ul>${section.items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></section>`).join('')}</details>`:''}</div></div><div class="eh-detail-bottom"><p>Source checked 20 November 2026. Price, equipment and availability require confirmation with Unicars. Published eHub snapshot; live inventory is not connected.</p>${button('Explore more cars','#available','secondary','car')}</div></div>`;bindImages(root)}catch(e){if(root.isConnected)error(root)}}
})();
